function check($v,$m){if(!$v)throw new RuntimeException($m);}
function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}define('BASE_URL','/chuyenmon/');
function require_login(){}function get_active_version_id(){return 'v1';}function get_version($id){return ['name'=>'Phiên bản kiểm thử','date'=>'2026-11-05'];}function get_assignment_stats($id){return ['slots_ok'=>2,'slots_missing'=>1,'total_std'=>12,'total_assigned'=>10,'total_diff'=>-2,'classes_ok'=>1,'classes_total'=>2,'missing_list'=>[['class'=>'6A','subject'=>'Toán','std'=>4]]];}function get_teacher_loads($id){return ['GV A'=>['total'=>20,'quota'=>18,'day'=>18,'role'=>2],'GV B'=>['total'=>16,'quota'=>18,'day'=>16,'role'=>0],'GV C'=>['total'=>18,'quota'=>18,'day'=>18,'role'=>0]];}function get_teachers_sorted(){return ['GV A','GV B','GV C'];}function get_classes(){return ['6A','6B'];}function get_assignments($id){return [['id'=>'a'],['id'=>'b']];}function get_role_assignments($id){return [['id'=>'r']];}function get_quota($t){return 18;}
function renderPccm($source){$source=preg_replace("~require_once '(?:includes/functions.php|includes/header.php|includes/footer.php)';~",'', $source);ob_start();eval('?>'.$source);return ob_get_clean();}
$source=file_get_contents(__DIR__.'/../chuyenmon/tongquan.php');$html=renderPccm($source);check(substr_count($html,'class="pccm-detail"')===4,'Four collapsed optional sections');check(!preg_match('/<details[^>]*\bopen\b/',$html),'Details closed initially');check(str_contains($html,'GV A')&&str_contains($html,'GV B')&&str_contains($html,'GV C'),'All teacher categories remain accessible');check(str_contains($html,'83.3%')&&str_contains($html,'-2.0'),'Original coverage and difference still rendered');
$baseline=getenv('CDS_PCCM_BASELINE');if($baseline&&is_file($baseline)){$old=file_get_contents($baseline);$marker="require_once 'includes/header.php';";check(explode($marker,$old)[0]===explode($marker,$source)[0],'Data loading, quota classification and sorting byte-identical');preg_match_all('~<table.*?</table>~s',renderPccm($old),$a);preg_match_all('~<table.*?</table>~s',$html,$b);check($a[0]===$b[0],'Every quota and missing-assignment table is unchanged');}
$css=file_get_contents(__DIR__.'/../chuyenmon/assets/pccm-overview.css');file_put_contents('/tmp/cm-menu-pccm-overview.html','<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="https://menu.test/bootstrap.css"><style>'.$css.'</style></head><body><main class="container">'.$html.'</main></body></html>');echo "PASS PCCM: unchanged data/calculation prefix and tables, all teacher categories retained, original coverage, details collapsed by default\n";
